package com.asmj.marketplace.favorite.service;import com.asmj.marketplace.favorite.model.Favorite;import com.asmj.marketplace.favorite.repository.FavoriteRepository;import com.asmj.marketplace.user.repository.UserRepository;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import java.time.Instant;import java.util.*;@Service@RequiredArgsConstructor public class FavoriteService{private final FavoriteRepository repo;private final UserRepository users;public Favorite add(String e,String p){String u=users.findByEmailIgnoreCase(e).orElseThrow().getId();return repo.findByUserIdAndPostId(u,p).orElseGet(()->repo.save(Favorite.builder().userId(u).postId(p).createdAt(Instant.now()).build()));}public void remove(String e,String p){String u=users.findByEmailIgnoreCase(e).orElseThrow().getId();repo.findByUserIdAndPostId(u,p).ifPresent(repo::delete);}public List<Favorite> mine(String e){return repo.findByUserId(users.findByEmailIgnoreCase(e).orElseThrow().getId());}}
